// Ko-fi manda el contenido como texto JSON en el campo «data».
// 1) Pega aquí el Verification Token de Ko-fi (ko-fi.com → Settings → API → Webhooks → Advanced).
const KOFI_TOKEN = 'PEGA_AQUI_EL_TOKEN_DE_KOFI';

const raw = $json.body?.data;
let d;
try {
  d = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return []; // no es de Ko-fi
}
if (!d || d.verification_token !== KOFI_TOKEN) return []; // aviso falso: se ignora
if (!['Donation', 'Subscription'].includes(d.type)) return []; // ventas de la tienda, comisiones, etc.

// Solo se envía lo necesario. El correo y el mensaje NO salen de n8n.
return [{
  json: {
    event_type: 'donation',
    client_payload: {
      id: d.kofi_transaction_id || d.message_id,
      name: d.from_name || '',
      method: 'kofi',
      amount: d.amount,
      currency: d.currency,
      public: d.is_public === true,
      source: d.type === 'Subscription' ? 'kofi-mensual' : 'kofi',
    },
  },
}];
